UPDATE ui.dashboardquery SET
vcdashboardquery = '{
    "All": {
        "Claimed": "select task.name_ as \"Stage\", task.assignee_ as \"Claimed By\", hiproinst.start_time_ \"Created Date\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \"Status\", pdef.name_ as \"Case Type\", CASE WHEN  task.assignee_ is not null and oplog.timestamp_ is not null THEN oplog.timestamp_ WHEN  task.assignee_ is not null and oplog.timestamp_ is null THEN task.create_time_ ELSE null END  as \"Claimed On\", payer.text_ as \"Payer\", payee.text_ as \"Payee\", TransactionAmount.double_ / 100 as \"Amount\", TicketID.long_ as \"Case ID\", Alert.text_ as \"Alert\" , null as  \"Closed Date\" , null as  \"Closed By\" , CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END  as \"VPA\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''observations''->''account''->>''vcexternalaccountid'' END  as \"Account\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''observations''->''customer''->>''vcexternalcustid'' END  as \"Customer\" from camunda.act_ru_task task right join camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_ full outer join camunda.act_hi_op_log oplog on oplog.id_ = (select id_ from camunda.act_hi_op_log where task_id_ = task.id_ and property_ = ''assignee'' and new_value_ = task.assignee_ order by timestamp_ desc limit 1) full outer join camunda.act_ru_variable payer on payer.proc_inst_id_ = task.proc_inst_id_ and payer.name_ = ''payer'' full outer join camunda.act_ru_variable payee on payee.proc_inst_id_ = task.proc_inst_id_ and payee.name_ = ''payee'' full outer join camunda.act_ru_variable  TransactionAmount on TransactionAmount.proc_inst_id_ = task.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' right join camunda.act_ru_variable  TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' full outer join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' full outer join camunda.act_hi_varinst  Txn on Txn.proc_inst_id_ = task.proc_inst_id_ and Txn.name_ = ''Transaction'' full outer join camunda.act_ge_bytearray Txnorg on Txnorg.id_ = Txn.bytearray_id_ inner join  camunda.act_hi_procinst hiproinst  on hiproinst.proc_inst_id_ = task.proc_inst_id_ where cast(hiproinst.start_time_ as date)  between cast(:StartDate as date) and cast(:EndDate as date)-1   and task.assignee_ is not null  and hiproinst.proc_def_key_ not in ( ''invoice'', ''ReviewInvoice'',''Orchestrator'', ''Sanctions'')",
        "Unclaimed": "select task.name_ as \"Stage\", task.assignee_ as \"Claimed By\", hiproinst.start_time_ \"Created Date\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \"Status\", pdef.name_ as \"Case Type\", CASE WHEN  task.assignee_ is not null and oplog.timestamp_ is not null THEN oplog.timestamp_ WHEN  task.assignee_ is not null and oplog.timestamp_ is null THEN task.create_time_ ELSE null END  as \"Claimed On\", payer.text_ as \"Payer\", payee.text_ as \"Payee\", TransactionAmount.double_ / 100 as \"Amount\", TicketID.long_ as \"Case ID\", Alert.text_ as \"Alert\" , null as  \"Closed Date\" ,null as  \"Closed By\" , CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END  as \"VPA\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''observations''->''account''->>''vcexternalaccountid'' END  as \"Account\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''observations''->''customer''->>''vcexternalcustid'' END  as \"Customer\" from camunda.act_ru_task task right join camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_ full outer join camunda.act_hi_op_log oplog on oplog.id_ = (select id_ from camunda.act_hi_op_log where task_id_ = task.id_ and property_ = ''assignee'' and new_value_ = task.assignee_ order by timestamp_ desc limit 1) full outer join camunda.act_ru_va